type Shape =
  | Circle(radius: Int)
  | Dot

fn size(s: Shape) -> Int {
    match s {
        Circle(diameter: d) => d    // ✗ `Circle` has no field `diameter`
        Dot => 0
    }
}

fn size(s: Shape) -> Int {
    match s {
        Circle(radius: r) => r    // ✓
        Dot => 0
    }
}
